def write_xml(folder: str, strings: dict) -> None:
    merged = dict(strings)
    merged.update(LANG_NAMES)
    dest = ROOT / folder
    dest.mkdir(parents=True, exist_ok=True)
    lines = ['<?xml version="1.0" encoding="utf-8"?>', "<resources>"]
    for key, value in merged.items():
        escaped = xml.escape(value, entities={'"': "&quot;", "'": "&apos;"})
        lines.append(f'    <string name="{key}">{escaped}</string>')
    lines.append("</resources>")
    (dest / "strings.xml").write_text("\n".join(lines) + "\n", encoding="utf-8")

def main():
    for folder, data in sorted(T.items()):
        write_xml(folder, data)
    print(f"Wrote {len(T)} locale files")

if __name__ == "__main__":
    main()
